def get_html() -> str:
    """Return the embedded nexa_interface.html as a string."""
    return gzip.decompress(base64.b64decode(_HTML_GZ_B64)).decode("utf-8")


def get_default_config() -> dict:
    """Return the embedded default nexa_config.json as a dict."""
    raw = gzip.decompress(base64.b64decode(_CONFIG_GZ_B64)).decode("utf-8")
    return json.loads(raw)


def get_default_config_str() -> str:
    """Return the embedded default nexa_config.json as a string."""
    return gzip.decompress(base64.b64decode(_CONFIG_GZ_B64)).decode("utf-8")
